//! Detect test, generated and minified code, and hash chunk text.

use sha2::Digest;
use sha2::Sha256;

use crate::code::language::CodeLanguage;
use crate::generated::generated;

const MAXIMUM_LINE_LENGTH: usize = 2000;

const MINIFIED_MINIMUM_LENGTH: usize = 1000;

const MINIFIED_WHITESPACE_RATIO: usize = 10;

const CONTENT_HASH_BYTES: usize = 8;

const GENERATED_MARKERS: &[&str] = &[
    "// Code generated",
    "// DO NOT EDIT",
    "// AUTO-GENERATED",
    "# Generated by",
    "/* eslint-disable */",
    "// @generated",
    "// This file was generated",
    "// GENERATED CODE",
];

pub(super) fn is_test_code(code: &str, language: CodeLanguage) -> bool {
    match language {
        CodeLanguage::Rust => {
            code.contains("#[test]") || code.contains("#[cfg(test)]") || code.contains("mod tests")
        }
        CodeLanguage::Python => {
            code.contains("def test_")
                || code.contains("class Test")
                || code.contains("unittest")
                || code.contains("pytest")
        }
        CodeLanguage::JavaScript | CodeLanguage::TypeScript | CodeLanguage::Tsx => {
            code.contains("describe(")
                || code.contains("it(")
                || code.contains("test(")
                || code.contains(".spec.")
                || code.contains(".test.")
        }
        CodeLanguage::Go => code.contains("func Test") || code.contains("testing.T"),
        CodeLanguage::Java => code.contains("@Test") || code.contains("junit"),
        CodeLanguage::Kotlin => code.contains("@Test") || code.contains("fun test"),
        CodeLanguage::Swift => code.contains("XCTest") || code.contains("func test"),
        _ => false,
    }
}

pub(super) fn is_likely_generated_or_minified(content: &str) -> bool {
    if generated("", content) {
        return true;
    }

    let maximum_line_length = content.lines().map(|line| line.len()).max().unwrap_or(0);
    if maximum_line_length > MAXIMUM_LINE_LENGTH {
        return true;
    }

    let lower = content.to_lowercase();
    for marker in GENERATED_MARKERS {
        if lower.contains(&marker.to_lowercase()) {
            return true;
        }
    }

    let total_characters = content.len();
    let whitespace_characters = content
        .chars()
        .filter(|character| character.is_whitespace())
        .count();
    if total_characters > MINIFIED_MINIMUM_LENGTH
        && whitespace_characters * MINIFIED_WHITESPACE_RATIO < total_characters
    {
        return true;
    }

    false
}

pub(super) fn compute_hash(content: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(content.as_bytes());
    hasher.finalize()[..CONTENT_HASH_BYTES]
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

pub(super) fn is_generated_path(path: &str) -> bool {
    let lower = path.to_lowercase();
    generated(path, "") || lower.contains("\\generated\\") || lower.contains("/vendor/")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_and_minified_content_is_detected() {
        assert!(!is_likely_generated_or_minified(
            "fn main() {\n    println!(\"hello\");\n}"
        ));

        assert!(is_likely_generated_or_minified(
            "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage pb"
        ));

        let minified = "a".repeat(3000);
        assert!(is_likely_generated_or_minified(&minified));
    }

    #[test]
    fn test_code_is_detected_per_language() {
        assert!(is_test_code(
            "#[test]\nfn test_something() {}",
            CodeLanguage::Rust
        ));
        assert!(is_test_code("def test_something():", CodeLanguage::Python));
        assert!(is_test_code(
            "describe('test', () => {})",
            CodeLanguage::JavaScript
        ));
        assert!(!is_test_code("fn main() {}", CodeLanguage::Rust));
    }

    #[test]
    fn content_hash_is_the_first_eight_sha256_bytes_in_hexadecimal() {
        assert_eq!(compute_hash("hello"), "2cf24dba5fb0a30e");
    }
}
